  }
  assert.equal(cases,32,'REGISTERED_CALLER_MATRIX');assert.deepEqual(requests,[expectedURL],'REGISTERED_REAL_QUEUE_AND_SELECTED_CACHE');assert.equal(box.__fq.length,0);assert.equal(box.__frunning,0);return cases;
 }finally{env.close();}
